import{_ as r,c as t,o as a,aS as e}from"./chunks/framework.BItddkxz.js";const g=JSON.parse('{"title":"树莓派（Raspberry Pi）","description":"","frontmatter":{"aside":"right"},"headers":[],"relativePath":"ops/raspberry-pi/index.md","filePath":"ops/raspberry-pi/index.md","lastUpdated":1772792710000}'),o={name:"ops/raspberry-pi/index.md"},s=e('<h1 id="树莓派-raspberry-pi" tabindex="-1">树莓派（Raspberry Pi） <a class="header-anchor" href="#树莓派-raspberry-pi" aria-label="Permalink to &quot;树莓派（Raspberry Pi）&quot;">​</a></h1><p>树莓派是由英国树莓派基金会推出的单板计算机（SBC），价格低廉、体积小巧，广泛用于教育、DIY、家庭服务器、物联网和边缘计算等场景。</p><h2 id="一、树莓派是什么" tabindex="-1">一、树莓派是什么 <a class="header-anchor" href="#一、树莓派是什么" aria-label="Permalink to &quot;一、树莓派是什么&quot;">​</a></h2><p>树莓派是一系列基于 ARM 的信用卡大小的电脑板，具备 GPIO 引脚、USB、HDMI 等接口，可运行 Linux（如 Raspberry Pi OS）。其初衷是让更多人能以低成本接触编程与计算机硬件，现已发展成为创客、运维和嵌入式开发中的常用平台。</p><h2 id="二、常见型号与选型" tabindex="-1">二、常见型号与选型 <a class="header-anchor" href="#二、常见型号与选型" aria-label="Permalink to &quot;二、常见型号与选型&quot;">​</a></h2><table><thead><tr><th>系列</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Raspberry Pi 5</strong></td><td>性能最强，PCIe、双 4K 输出</td><td>桌面替代、小型服务器</td></tr><tr><td><strong>Raspberry Pi 4</strong></td><td>多代同堂，内存 1GB～8GB</td><td>家用服务器、软路由、媒体中心</td></tr><tr><td><strong>Raspberry Pi 3 / Zero 2 W</strong></td><td>功耗低、带无线</td><td>物联网、监控、便携设备</td></tr><tr><td><strong>Raspberry Pi Zero / Pico</strong></td><td>极小体积、超低成本</td><td>嵌入式、穿戴、简单控制</td></tr></tbody></table><p>选型时可优先考虑：是否需要无线（Wi‑Fi/蓝牙）、内存大小、GPIO 与扩展需求，以及供电与散热。</p><h2 id="三、系统与首次使用" tabindex="-1">三、系统与首次使用 <a class="header-anchor" href="#三、系统与首次使用" aria-label="Permalink to &quot;三、系统与首次使用&quot;">​</a></h2><h3 id="官方系统-raspberry-pi-os" tabindex="-1">官方系统 Raspberry Pi OS <a class="header-anchor" href="#官方系统-raspberry-pi-os" aria-label="Permalink to &quot;官方系统 Raspberry Pi OS&quot;">​</a></h3><ul><li>基于 <strong>Debian</strong>，与 Ubuntu 同源，使用 <strong>apt</strong> 包管理。</li><li>镜像下载：<a href="https://www.raspberrypi.com/software/operating-systems/" target="_blank" rel="noreferrer">Raspberry Pi OS – Raspberry Pi</a>。</li><li>烧录工具推荐：<strong>Raspberry Pi Imager</strong>（支持多系统、预配置 Wi‑Fi 与 SSH）。</li></ul><h3 id="首次启动建议" tabindex="-1">首次启动建议 <a class="header-anchor" href="#首次启动建议" aria-label="Permalink to &quot;首次启动建议&quot;">​</a></h3><ol><li>使用 Imager 时勾选「设置」：开启 <strong>SSH</strong>、设置主机名、用户名与密码、配置 <strong>Wi‑Fi</strong>（可选）。</li><li>若未预配置，将存有 <code>ssh</code> 或 <code>wpa_supplicant.conf</code> 的 U 盘插入树莓派，或接显示器键盘进行首次配置。</li><li>通过 <code>ssh pi@&lt;树莓派IP&gt;</code> 或默认主机名 <code>raspberrypi.local</code> 登录。</li></ol><div class="tip custom-block"><p class="custom-block-title">与 Ubuntu 的相似处</p><p>Raspberry Pi OS 使用 systemd、apt、UFW 等，多数 <a href="/ops/linux/常见操作/">Linux 常见操作</a> 与 <a href="/ops/linux/基本配置/基本配置.html">基本配置</a> 思路可直接沿用。</p></div><h2 id="四、常见用途" tabindex="-1">四、常见用途 <a class="header-anchor" href="#四、常见用途" aria-label="Permalink to &quot;四、常见用途&quot;">​</a></h2><ul><li><strong>家庭服务器 / NAS</strong>：挂载硬盘、跑 Docker、Samba/NFS 共享。</li><li><strong>软路由 / 旁路由</strong>：配合 OpenWRT 或自建网关，实现代理、去广告等。</li><li><strong>智能家居与物联网</strong>：Home Assistant、Node-RED，或通过 GPIO 控制传感器与继电器。</li><li><strong>学习与开发</strong>：Python/GPIO 编程、K8s 节点、CI Runner、小型数据库与 Web 服务。</li><li><strong>媒体中心</strong>：Kodi、Jellyfin 等，接电视或显示器播放。</li></ul><h2 id="五、常用资源" tabindex="-1">五、常用资源 <a class="header-anchor" href="#五、常用资源" aria-label="Permalink to &quot;五、常用资源&quot;">​</a></h2><table><thead><tr><th>资源</th><th>链接</th></tr></thead><tbody><tr><td>官网与文档</td><td><a href="https://www.raspberrypi.com/documentation/" target="_blank" rel="noreferrer">raspberrypi.com</a></td></tr><tr><td>镜像与 Imager</td><td><a href="https://www.raspberrypi.com/software/" target="_blank" rel="noreferrer">Raspberry Pi OS 下载与安装</a></td></tr><tr><td>GPIO 与硬件</td><td><a href="https://pinout.xyz/" target="_blank" rel="noreferrer">pinout.xyz</a>（引脚说明）</td></tr><tr><td>论坛与社区</td><td><a href="https://forums.raspberrypi.com/" target="_blank" rel="noreferrer">Raspberry Pi Forums</a></td></tr></tbody></table><p>后续可在本目录下按主题新增子页（如「系统安装与备份」「Docker 与 Home Assistant」「GPIO 入门」等），与 <a href="/ops/linux/">Linux</a>、<a href="/ops/openwrt/">OpenWRT</a> 等运维文档配合使用。</p>',18),i=[s];function n(d,l,p,h,b,c){return a(),t("div",null,i)}const y=r(o,[["render",n]]);export{g as __pageData,y as default};
